-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.100.0',
  '2026-09-23',
  'Настройки: профиль, свои устройства, поиск и сворачивание секций',
  E'Наверху страницы настроек появился «Профиль»: имя, id, чем выполнен вход (Telegram или токен), первый и последний заход и часовой пояс вашего устройства. Там же — «Мои устройства и сеансы»: с каких устройств и адресов заходили в приложение. Раньше это видел только админ в чужой карточке, а владельцу не показывалось.\n\nКнопка «Отозвать все токены доступа» разом закрывает вход в веб-версию и расширение на всех устройствах. Вход в Telegram она не трогает — его сеанс подписывает сам Telegram, и приложение отозвать его не может; так и написано рядом.\n\nСверху — поиск по настройкам: набираете «фон» или «токен», и остаются только нужные разделы. Сворачиваются теперь все разделы, а не только «Оформление», и свёрнутость запоминается на сервере — на другом устройстве страница откроется так же.',
  E'Бэкенд: GET /settings/profile (store.SelfProfile — те же поля, что у админской карточки, но без восьми COUNT(*)) и POST /settings/tokens/revoke-all (store.RevokeAllAccessTokens, проставляет revoked_at всем активным). Сеансы Telegram не отзываются принципиально: initData подписан Telegram.\n\nФронтенд: SettingsView переписан на SettingsSection — обёртку с заголовком, стрелкой и участием в поиске. Состояние страницы (строка поиска и свёрнутость) раздаётся через provide/inject (ключи в apps/settings/sections.ts), там же список секций с ключевыми словами для поиска; номер секции — он же ключ свёрнутости на сервере, поэтому «Оформление» сохранило id 1. Во время поиска секции принудительно раскрыты и заголовок не кликается. У VisiblePages и AccessTokens убраны собственные рамка и заголовок — их рисует обёртка.\n\nshared/collapsed.ts: запросы по одному приложению сериализованы. Два быстрых сворачивания подряд улетали двумя PUT, сервер применял их в обратном порядке, и второй блок разворачивался сам после перезагрузки (поймано на проверке).\n\nПроверено в браузере: профиль и список устройств, отзыв всех токенов (1 → 0), поиск по «фон» (остаётся «Оформление») и по несуществующему слову, сворачивание трёх секций подряд и их состояние после перезагрузки.'
);
-- +goose StatementEnd

